import{_ as e,H as l,f as a,i as d}from"./chunks/framework.DLd0CbzH.js";const c=JSON.parse('{"title":"Онбординг клиента — Agelto","description":"","frontmatter":{"type":"workflow","tags":["agelto","workflow","onboarding","customer-success"],"created":"2026-06-11T00:00:00.000Z","updated":"2026-06-11T00:00:00.000Z"},"headers":[],"relativePath":"02_Workflow/Onboarding.md","filePath":"02_Workflow/Onboarding.md"}'),i={name:"02_Workflow/Onboarding.md"};function r(n,t,o,s,g,f){return l(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="онбординг-клиента-—-agelto" tabindex="-1">Онбординг клиента — Agelto <a class="header-anchor" href="#онбординг-клиента-—-agelto" aria-label="Permalink to &quot;Онбординг клиента — Agelto&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">Назначение</p><p>Путь клиента от регистрации до первого лида (Time-to-Value). Главная митигация churn-риска ([[Risk_Register (Agelto)]] R-3). Требования — [[BRD (Agelto)]] §4.3, §7.</p></div><hr><h2 id="целевая-метрика" tabindex="-1">Целевая метрика <a class="header-anchor" href="#целевая-метрика" aria-label="Permalink to &quot;Целевая метрика&quot;">​</a></h2><p><strong>TTV (Time-to-Value): ≤ 3 рабочих дня</strong> от регистрации до первого верифицированного лида в кабинете. Дольше — растёт риск отвала до оплаты.</p><hr><h2 id="процесс" tabindex="-1">Процесс <a class="header-anchor" href="#процесс" aria-label="Permalink to &quot;Процесс&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Шаг</th><th style="text-align:left;">Действие</th><th style="text-align:left;">Кто</th><th style="text-align:left;">SLA</th></tr></thead><tbody><tr><td style="text-align:left;">1. Регистрация</td><td style="text-align:left;">Аккаунт + 2FA, выбор тарифа (или пилот)</td><td style="text-align:left;">Клиент</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">2. Загрузка Коллекции</td><td style="text-align:left;">Импорт прайс-листа (Excel/CSV) → валидация (F-MATCH-1) → отчёт об ошибках</td><td style="text-align:left;">Клиент (Commercial Director)</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">3. Чистка данных</td><td style="text-align:left;">Исправление невалидных строк по отчёту; при Setup Service — делает Agelto</td><td style="text-align:left;">Клиент / Agelto</td><td style="text-align:left;">1 день</td></tr><tr><td style="text-align:left;">4. Индексация</td><td style="text-align:left;">Embeddings строятся в фоне, статус «Коллекция обновляется»</td><td style="text-align:left;">Система</td><td style="text-align:left;">часы</td></tr><tr><td style="text-align:left;">5. Настройка фильтров</td><td style="text-align:left;">Регионы, ОКПД2, ценовой диапазон, порог Score</td><td style="text-align:left;">Клиент + Agelto</td><td style="text-align:left;">1 день</td></tr><tr><td style="text-align:left;">6. Первые матчи</td><td style="text-align:left;">Прогон по свежим тендерам, премодерация ([[Lead_Verification]])</td><td style="text-align:left;">Система + Analyst</td><td style="text-align:left;">1 день</td></tr><tr><td style="text-align:left;">7. CRM-подключение</td><td style="text-align:left;">Bitrix24/amoCRM webhook (после пилота — F-CRM-1)</td><td style="text-align:left;">Agelto</td><td style="text-align:left;">—</td></tr><tr><td style="text-align:left;">8. Обучение</td><td style="text-align:left;">Демо кабинета менеджерам клиента</td><td style="text-align:left;">Customer Success</td><td style="text-align:left;">1 сессия</td></tr></tbody></table><h2 id="setup-service-платныи-f-mon-4" tabindex="-1">Setup Service (платный, F-MON-4) <a class="header-anchor" href="#setup-service-платныи-f-mon-4" aria-label="Permalink to &quot;Setup Service (платный, F-MON-4)&quot;">​</a></h2><p>Шаги 2–8 «под ключ»: чистка прайс-листа, настройка фильтров, CRM-интеграция, обучение персонала. Для Enterprise — обязательная рекомендация.</p><h2 id="не-реализовано-открыто" tabindex="-1">Не реализовано / открыто <a class="header-anchor" href="#не-реализовано-открыто" aria-label="Permalink to &quot;Не реализовано / открыто&quot;">​</a></h2><ul><li>Self-service onboarding UI — после пилотной фазы (на пилоте шаги ведёт команда вручную)</li><li>Кто выполняет роль Analyst на шаге 6 — [[Открытые вопросы (Agelto)]] P6</li></ul>',12)])])}const h=e(i,[["render",r]]);export{c as __pageData,h as default};
